/* A substituted node inherits the parenthesization of the node it replaces:
 * the gap or the macro invocation was written parenthesized, so its
 * expansion is parenthesized too.
 */
private static Node carryParentheses(Node replaced, Node result) {
    if (replaced instanceof Expr && result instanceof Expr &&
        NodeUtil.isParenthesized((Expr) replaced) &&
        !NodeUtil.isParenthesized((Expr) result)) {
        return ExprFactory.makeInParentheses((Expr) result);
    }
    return result;
}

