59	     * nodes so that only a core Fortress AST is left.
60	     */
61	    public static Node transform(GlobalEnvironment env, Node node) {
62	        Transform transform = new Transform(populateTransformers(env),
63	                                            /* map of variables and their ellipses depth */
64	                                            new HashMap<String, Level>(),
65	                                            /* hygiene */
66	                                            SyntaxEnvironment.identityEnvironment(), false);
67	        /* goes to defaultTransformationNodeCase */
